UPDATE user
SET user_name = #{userName},
    phone = #{phone}
WHERE email = #{email}

UPDATE user_person up
JOIN user u ON up.user_id = u.user_id
SET up.gender = #{gender},
    up.birth_date = #{birthDate},
    up.country = #{country}
WHERE u.email = #{email}

